import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';

export default defineConfig({
  plugins: [react()],
  server: {
    proxy: {
      '/replay': 'http://localhost:8080',
      '/scenarios': 'http://localhost:8080',
      '/healthz': 'http://localhost:8080',
      '/metrics': 'http://localhost:8080'
    }
  }
});

import React from 'react';
import ReactDOM from 'react-dom/client';
import { BrowserRouter } from 'react-router-dom';
import App from './App';

import './index.css';

ReactDOM.createRoot(document.getElementById('root')!).render(
  <React.StrictMode>
    <BrowserRouter>
      <App />
    </BrowserRouter>
  </React.StrictMode>
);

import React from 'react';
import { Routes, Route, Link, Navigate } from 'react-router-dom';
import Scenarios from './pages/Scenarios';
import StartReplay from './pages/StartReplay';
import Runs from './pages/Runs';
import RunReport from './pages/RunReport';

const App: React.FC = () => {
  return (
    <div>
      <nav style={{ padding: '1rem', borderBottom: '1px solid #ccc' }}>
        <Link to="/scenarios" style={{ marginRight: 10 }}>
          Scenarios
        </Link>
        <Link to="/start-replay" style={{ marginRight: 10 }}>
          Start Replay
        </Link>
        <Link to="/runs" style={{ marginRight: 10 }}>
          Runs
        </Link>
      </nav>
      <div style={{ padding: '1rem' }}>
        <Routes>
          <Route path="/" element={<Navigate to="/scenarios" replace />} />
          <Route path="/scenarios" element={<Scenarios />} />
          <Route path="/start-replay" element={<StartReplay />} />
          <Route path="/runs" element={<Runs />} />
          <Route path="/runs/:runId" element={<RunReport />} />
          <Route path="*" element={<div>Page Not Found</div>} />
        </Routes>
      </div>
    </div>
  );
};

export default App;

import React from 'react';

const Scenarios: React.FC = () => {
  return (
    <div>
      <h1>Scenarios</h1>
      <p>Basic page skeleton for Scenarios management.</p>
    </div>
  );
};

export default Scenarios;

import React from 'react';

const StartReplay: React.FC = () => {
  return (
    <div>
      <h1>Start Replay</h1>
      <p>Basic page skeleton for starting a replay.</p>
    </div>
  );
};

export default StartReplay;

import React from 'react';
import { Link } from 'react-router-dom';

const Runs: React.FC = () => {
  return (
    <div>
      <h1>Runs</h1>
      <p>Basic page skeleton listing replay runs.</p>
      <p>
        Example run link: <Link to="/runs/run-1234567890">run-1234567890</Link>
      </p>
    </div>
  );
};

export default Runs;

import React from 'react';
import { useParams } from 'react-router-dom';

const RunReport: React.FC = () => {
  const { runId } = useParams<{ runId: string }>();

  return (
    <div>
      <h1>Run Report</h1>
      <p>Basic page skeleton for Run Report details.</p>
      <p>Run ID: {runId}</p>
    </div>
  );
};

export default RunReport;

/* Basic CSS reset and styling */
body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Oxygen,
    Ubuntu, Cantarell, "Open Sans", "Helvetica Neue", sans-serif;
  background-color: #fafafa;
  color: #333;
}
a {
  color: #0366d6;
  text-decoration: none;
}
a:hover {
  text-decoration: underline;
}
